import json,sys
for l in open(sys.argv[1]):
    d=json.loads(l)
    if d.get('type')=='user':
        c=d['message']['content']
        if isinstance(c,list):
            c=' '.join(x.get('text','') for x in c if x.get('type')=='text')
        if c.strip() and not c.startswith('<'):
            print(d.get('timestamp'), c[:300].replace('\n',' '))
    if d.get('type')=='assistant':
        m=d['message']
        if m.get('model'): last=m['model']
print('model',last)
EOF
done; git -C /home/michal-jankowski/pwr/digital-media-analysis ls-files src tests notebooks | head -30

